/**
 * The equivalence corpus: every script here is inside the subset and must
 * produce, on tinybash, byte for byte what GNU bash 5.2 with coreutils 9.4
 * produced (`goldens/<name>.json`, regenerated by `generate.ts`).
 *
 * `linuxOnly` marks cases whose output depends on the filesystem underneath
 * (directory sizes and block counts in `ls -l`); they are compared only when
 * the tests themselves run on Linux.
 *
 * Names must stay distinct case-insensitively: goldens are files, and the
 * repository may live on a case-insensitive filesystem.
 */
export interface CorpusCase {
  name: string
  script: string
  linuxOnly?: boolean
}

